        StringTokenizer tz = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(tz.nextToken());
        int m = Integer.parseInt(tz.nextToken());
        int[][] matrix = new int[n][m];
        for (int i=0; i<n; i++) {
